package io.stintflow.sandbox.privacy.filter;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.List;

import org.junit.jupiter.api.Test;

import io.stintflow.sandbox.contracts.Corpus;
import io.stintflow.worker.redaction.LayeredRedactor;
import io.stintflow.worker.redaction.Pseudonyms;
import io.stintflow.worker.redaction.RedactionLayer;
import io.stintflow.worker.redaction.RedactionLayer.Scope;

/**
 * SDD S.6, CA1: each layer on its own — the forms generated by rule and the ones Whisper wrote in the S.5 manual run
 * (CA7) — and the layers composed. Synthetic data only.
 */
class LayersTest {

    static final Corpus CORPUS = Corpus.load(Path.of(System.getProperty("sandbox.root", "..")).resolve("corpus"));
    static final Scope SCOPE = new Scope("i-1", java.util.Set.of(),
            new Pseudonyms("layers-test-secret-0123456789".getBytes(StandardCharsets.UTF_8)));

    static String apply(RedactionLayer layer, String text) {
        return layer.apply(text, SCOPE).text();
    }

    // --- spoken forms ---------------------------------------------------------------------------------------------

    @Test
    void a_dictated_email_is_replaced_in_the_forms_whisper_writes() {
        SpokenFormLayer layer = new SpokenFormLayer();
        for (String spoken : List.of("synth p i i zero two zero one at example dot com",
                "Sinthe-P-I-I-2-0-2-1 at Example. Calm.", "j o h n at example dot org")) {
            String out = apply(layer, "Write to " + spoken + " please.");
            assertThat(out).as(spoken).startsWith("Write to ").endsWith(" please.").contains("SPOKEN-EMAIL")
                    .doesNotContain("example").doesNotContain("Example");
        }
    }

    @Test
    void a_dictated_number_of_seven_digits_or_more_is_replaced() {
        SpokenFormLayer layer = new SpokenFormLayer();
        assertThat(apply(layer, "Call plus five five one one nine eight zero two two four zero two two now."))
                .contains("SPOKEN-NUMBER").doesNotContain("five five").endsWith(" now.");
        assertThat(apply(layer, "My number is plus 5511 98022 4022 thanks.")).contains("SPOKEN-NUMBER")
                .doesNotContain("98022");
        // a short run is a quantity, not a number
        assertThat(apply(layer, "We need two or three more, maybe 2011 or 40.")).doesNotContain("SPOKEN-NUMBER");
    }

    @Test
    void spelled_letters_are_replaced_but_ordinary_text_is_not() {
        SpokenFormLayer layer = new SpokenFormLayer();
        assertThat(apply(layer, "It is spelled p-i-i in the system.")).contains("SPELLED").doesNotContain("p-i-i");
        assertThat(apply(layer, "I am a product owner and I like it.")).doesNotContain("SPELLED");
    }

    // --- names ----------------------------------------------------------------------------------------------------

    @Test
    void a_listed_name_is_found_a_letter_short_and_with_the_surname() {
        NameLayer layer = new NameLayer(LayeredFilter.namesOf(CORPUS));
        for (String spoken : List.of("I am synth PI 2011 Rivera product owner.",       // seen in S.5 CA7
                "I am SYNTH-PII-2011 Rivera, product owner.", "I am synth p i i two zero one one rivera product owner.")) {
            String out = apply(layer, spoken);
            assertThat(CORPUS.leaksIn(out)).as(spoken).isEmpty();
            assertThat(out).as(spoken).contains("PERSON").doesNotContain("Rivera").doesNotContain("rivera")
                    .endsWith("product owner.");
        }
    }

    @Test
    void text_that_is_not_a_listed_name_is_left_alone() {
        NameLayer layer = new NameLayer(LayeredFilter.namesOf(CORPUS));
        String text = "The synth sound of the pi value is 3.14 in 2011.";
        assertThat(apply(layer, text)).isEqualTo(text);
    }

    @Test
    void an_introduced_name_is_replaced_but_a_day_is_not() {
        PresentationLayer layer = new PresentationLayer();
        assertThat(apply(layer, "Hi, I am Maria Souza, the product owner.")).contains("PERSON")
                .doesNotContain("Maria").doesNotContain("Souza").contains("the product owner.");
        assertThat(apply(layer, "My name is Joao and this is Friday.")).doesNotContain("Joao").contains("Friday");
    }

    // --- composed -------------------------------------------------------------------------------------------------

    @Test
    void the_layers_compose_and_report_their_counts() {
        LayeredRedactor filter = LayeredFilter.build(LayeredFilter.namesOf(CORPUS), null, 0.5);
        String text = "I am synth PI 2011 Rivera product owner. Mail synth p i i two zero one two at example dot com or "
                + "call plus five five one one nine eight zero two two four zero two two.";
        RedactionLayer.Result result = filter.redact(text, SCOPE);
        assertThat(CORPUS.leaksIn(result.text())).isEmpty();
        assertThat(result.counts()).containsKeys("person", "spoken-email", "spoken-number");
        assertThat(result.doubt()).isFalse();
        assertThat(filter.layerNames()).containsExactly("patterns", "spoken", "names", "presentation");
    }
}
